SELECT ?importedOntology ?externalReference
WHERE {
    <https://saref.etsi.org/saref4envi/> rdf:type owl:Ontology .
    OPTIONAL { <https://saref.etsi.org/saref4envi/> owl:imports ?importedOntology }
    OPTIONAL { <https://saref.etsi.org/saref4envi/> rdfs:seeAlso ?externalReference }
}

