SELECT ?unit
WHERE {
    ?unit rdf:type s4envi:FrequencyUnit .
    ?unit rdf:type owl:NamedIndividual .
    FILTER(?unit = <http://www.wurvoc.org/vocabularies/om-1.8/reciprocal_second-time>)
}

